package com.onlymymoney.adapter.out.persistence;

import com.onlymymoney.domain.model.ImportStatus;
import jakarta.persistence.*;

import java.math.BigDecimal;
import java.time.*;

/**
 * JPA entity mapped to the {@code movements} table.
 * <p>
 * It is the persistence representation of a bank movement, which belongs to an account and
 * can optionally be assigned to a category.
 */
@Entity
@Table(name = "movements")
public class MovementJpa {
    /** Primary key, generated by the database (identity column). */
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    Long id;
    /** Identifier of the account this movement belongs to. */
    @Column(name = "account_id")
    Long accountId;
    /** Concept or description of the movement. */
    String concept;
    /** Date on which the movement took place. */
    @Column(name = "movement_date")
    LocalDate movementDate;
    /** Amount of the movement, stored with precision 19 and scale 2. */
    @Column(precision = 19, scale = 2)
    BigDecimal amount;
    /** Available balance reported after the movement, stored with precision 19 and scale 2. */
    @Column(name = "available_balance", precision = 19, scale = 2)
    BigDecimal availableBalance;
    /** Import status of the movement, persisted as text (the enum name) rather than its ordinal. */
    @Enumerated(EnumType.STRING)
    @Column(name = "import_status")
    ImportStatus importStatus;
    /** Identifier of the category assigned to the movement, if any. */
    @Column(name = "category_id")
    Long categoryId;
    /** Timestamp of when the record was created. */
    @Column(name = "created_at")
    Instant createdAt;

    /**
     * Default constructor required by JPA.
     */
    public MovementJpa() {
    }

    /**
     * Creates an entity with all its fields.
     *
     * @param id  the identifier ({@code null} for a new movement)
     * @param a   the account identifier
     * @param c   the concept
     * @param d   the movement date
     * @param am  the amount
     * @param b   the available balance
     * @param s   the import status
     * @param cat the category identifier, or {@code null} if not assigned
     * @param t   the creation timestamp
     */
    public MovementJpa(Long id, Long a, String c, LocalDate d, BigDecimal am, BigDecimal b, ImportStatus s, Long cat, Instant t) {
        this.id = id;
        accountId = a;
        concept = c;
        movementDate = d;
        amount = am;
        availableBalance = b;
        importStatus = s;
        categoryId = cat;
        createdAt = t;
    }

    /** @return the movement identifier */
    public Long getId() {
        return id;
    }

    /** @return the identifier of the account the movement belongs to */
    public Long getAccountId() {
        return accountId;
    }

    /** @return the concept of the movement */
    public String getConcept() {
        return concept;
    }

    /** @return the date of the movement */
    public LocalDate getMovementDate() {
        return movementDate;
    }

    /** @return the amount of the movement */
    public BigDecimal getAmount() {
        return amount;
    }

    /** @return the available balance after the movement */
    public BigDecimal getAvailableBalance() {
        return availableBalance;
    }

    /** @return the import status of the movement */
    public ImportStatus getImportStatus() {
        return importStatus;
    }

    /** @return the identifier of the assigned category, or {@code null} if none */
    public Long getCategoryId() {
        return categoryId;
    }

    /** @return the timestamp of when the record was created */
    public Instant getCreatedAt() {
        return createdAt;
    }
}